class_name State
extends Node

signal transitioned(state: State, new_state_name: String)


func enter() -> void:
	pass


func exit() -> void:
	pass


func update(_delta: float) -> void:
	pass


func physics_update(_delta: float) -> void:
	pass

class_name StateMachine
extends Node

@export var initial_state: State

var current_state: State
var states: Dictionary = {}


func _ready() -> void:
	await owner.ready
	for child in get_children():
		if child is State:
			states[child.name.to_lower()] = child
			child.transitioned.connect(_on_child_transitioned)

	if initial_state:
		initial_state.enter()
		current_state = initial_state


func _process(delta: float) -> void:
	if current_state:
		current_state.update(delta)


func _physics_process(delta: float) -> void:
	if current_state:
		current_state.physics_update(delta)


func _on_child_transitioned(state: State, new_state_name: String) -> void:
	if state != current_state:
		return

	var new_state: State = states.get(new_state_name.to_lower())
	if not new_state:
		return

	if current_state:
		current_state.exit()

	new_state.enter()
	current_state = new_state

class_name PlayerIdleState
extends State

@export var player: CharacterBody2D
@export var animated_sprite: AnimatedSprite2D


func enter() -> void:
	if animated_sprite:
		animated_sprite.play("idle")


func physics_update(delta: float) -> void:
	player.apply_gravity(delta)
	player.apply_movement(0.0, delta)

	if not player.is_on_floor():
		transitioned.emit(self, "fall")
		return

	if Input.is_action_pressed("crouch"):
		transitioned.emit(self, "crouch")
		return

	if Input.is_action_just_pressed("jump"):
		transitioned.emit(self, "jump")
		return

	var direction := Input.get_axis("move_left", "move_right")
	if direction != 0.0:
		transitioned.emit(self, "run")

class_name PlayerRunState
extends State

@export var player: CharacterBody2D
@export var animated_sprite: AnimatedSprite2D


func enter() -> void:
	if animated_sprite:
		animated_sprite.play("run")


func physics_update(delta: float) -> void:
	player.apply_gravity(delta)
	var direction := Input.get_axis("move_left", "move_right")
	player.apply_movement(direction, delta)

	if not player.is_on_floor():
		transitioned.emit(self, "fall")
		return

	if Input.is_action_pressed("crouch"):
		transitioned.emit(self, "crouch")
		return

	if Input.is_action_just_pressed("jump"):
		transitioned.emit(self, "jump")
		return

	if direction == 0.0 and absf(player.velocity.x) < 1.0:
		transitioned.emit(self, "idle")

class_name Door
extends StaticBody2D

var is_open: bool = false

@onready var animation_player: AnimationPlayer = $AnimationPlayer


func open() -> void:
	if animation_player:
		animation_player.play("open")


func door_opened() -> void:
	is_open = true

class_name MovingPlatform
extends AnimatableBody2D

@export var move_offset: Vector2 = Vector2(200.0, 0.0)
@export var speed: float = 80.0

var _start_position: Vector2
var _target_position: Vector2
var _moving_to_target: bool = true


func _ready() -> void:
	_start_position = global_position
	_target_position = _start_position + move_offset


func _physics_process(delta: float) -> void:
	var destination := _target_position if _moving_to_target else _start_position
	global_position = global_position.move_toward(destination, speed * delta)

	if global_position.distance_to(destination) < 1.0:
		_moving_to_target = not _moving_to_target

class_name PlayerCrouchState
extends State

@export var player: CharacterBody2D
@export var animated_sprite: AnimatedSprite2D


func enter() -> void:
	if animated_sprite:
		animated_sprite.play("idle")
	player.velocity.x = 0.0


func physics_update(delta: float) -> void:
	player.apply_gravity(delta)
	player.move_and_slide()

	if not player.is_on_floor():
		transitioned.emit(self, "fall")
		return

	if Input.is_action_just_pressed("jump"):
		player.position.y += 2.0
		transitioned.emit(self, "fall")
		return

	if not Input.is_action_pressed("crouch"):
		var direction := Input.get_axis("move_left", "move_right")
		if direction != 0.0:
			transitioned.emit(self, "run")
		else:
			transitioned.emit(self, "idle")

class_name Ladder
extends Area2D


func _ready() -> void:
	body_entered.connect(_on_body_entered)
	body_exited.connect(_on_body_exited)


func _on_body_entered(body: Node2D) -> void:
	if body is CharacterBody2D and "is_on_ladder" in body:
		body.is_on_ladder = true


func _on_body_exited(body: Node2D) -> void:
	if body is CharacterBody2D and "is_on_ladder" in body:
		body.is_on_ladder = false

class_name Hazard
extends Area2D

@export var damage: int = 1


func _ready() -> void:
	body_entered.connect(_on_body_entered)


func _on_body_entered(body: Node2D) -> void:
	if body.has_method("take_damage"):
		body.take_damage(damage)

class_name Checkpoint
extends Area2D

signal activated(new_position: Vector2)

var is_active: bool = false


func _ready() -> void:
	body_entered.connect(_on_body_entered)


func _on_body_entered(body: Node2D) -> void:
	if is_active:
		return

	if body.is_in_group("player"):
		is_active = true
		activated.emit(global_position)

class_name LevelManager
extends Node

signal item_collected(current_count: int, total_required: int)
signal level_completed

@export var total_items_required: int = 3
@export_file("*.tscn") var next_level_path: String = ""

var collected_items: int = 0


func collect_item() -> void:
	collected_items += 1
	item_collected.emit(collected_items, total_items_required)


func can_complete_level() -> bool:
	return collected_items >= total_items_required


func complete_level() -> void:
	if can_complete_level():
		level_completed.emit()
		if not next_level_path.is_empty():
			get_tree().change_scene_to_file(next_level_path)

class_name Goal
extends Area2D

@export_file("*.tscn") var next_level_path: String = ""


func _ready() -> void:
	body_entered.connect(_on_body_entered)


func _on_body_entered(body: Node2D) -> void:
	if body is CharacterBody2D:
		_reach_goal()


func _reach_goal() -> void:
	if next_level_path.is_empty():
		return
	get_tree().change_scene_to_file(next_level_path)

class_name WalkerEnemy
extends CharacterBody2D

@export var speed: float = 60.0
@export var gravity: float = 980.0
@export var bounce_impulse: float = -320.0
@export var damage: int = 1
@export var death_particles_scene: PackedScene = preload("res://effects/enemy_explosion.tscn")

var direction: float = 1.0

@onready var sprite: Sprite2D = $Sprite2D
@onready var edge_detector: RayCast2D = $EdgeDetector
@onready var stomp_area: Area2D = $StompArea
@onready var hit_area: Area2D = $HitArea


func _ready() -> void:
	if stomp_area:
		stomp_area.body_entered.connect(_on_stomp_area_body_entered)
	if hit_area:
		hit_area.body_entered.connect(_on_hit_area_body_entered)


func _physics_process(delta: float) -> void:
	if not is_on_floor():
		velocity.y += gravity * delta

	if is_on_wall() or (is_on_floor() and edge_detector and not edge_detector.is_colliding()):
		_turn_around()

	velocity.x = direction * speed
	move_and_slide()


func _turn_around() -> void:
	direction *= -1.0
	if sprite:
		sprite.flip_h = direction < 0.0
	if edge_detector:
		edge_detector.position.x = absf(edge_detector.position.x) * direction


func _on_stomp_area_body_entered(body: Node2D) -> void:
	if is_queued_for_deletion():
		return
	if body is CharacterBody2D and body.velocity.y >= 0.0:
		body.velocity.y = bounce_impulse
		if death_particles_scene:
			var particles := death_particles_scene.instantiate() as GPUParticles2D
			particles.global_position = global_position
			get_parent().add_child(particles)
		queue_free()


func _on_hit_area_body_entered(body: Node2D) -> void:
	if is_queued_for_deletion():
		return
	if body.is_in_group("player") and body.has_method("take_damage"):
		if body is CharacterBody2D and body.velocity.y > 0.0 and body.global_position.y < global_position.y:
			return
		body.take_damage(damage)

class_name FlyingEnemy
extends CharacterBody2D

@export var speed: float = 80.0
@export var patrol_time: float = 2.0
@export var bounce_impulse: float = -320.0
@export var damage: int = 1
@export var death_particles_scene: PackedScene = preload("res://effects/enemy_explosion.tscn")

var direction: float = 1.0

@onready var sprite: Sprite2D = $Sprite2D
@onready var patrol_timer: Timer = $PatrolTimer
@onready var stomp_area: Area2D = $StompArea
@onready var hit_area: Area2D = $HitArea


func _ready() -> void:
	if patrol_timer:
		patrol_timer.wait_time = patrol_time
		patrol_timer.timeout.connect(_on_patrol_timer_timeout)
		patrol_timer.start()

	if stomp_area:
		stomp_area.body_entered.connect(_on_stomp_area_body_entered)
	if hit_area:
		hit_area.body_entered.connect(_on_hit_area_body_entered)


func _physics_process(_delta: float) -> void:
	if is_on_wall():
		_turn_around()
		if patrol_timer:
			patrol_timer.start()

	velocity.x = direction * speed
	velocity.y = 0.0
	move_and_slide()


func _turn_around() -> void:
	direction *= -1.0
	if sprite:
		sprite.flip_h = direction < 0.0


func _on_patrol_timer_timeout() -> void:
	_turn_around()


func _on_stomp_area_body_entered(body: Node2D) -> void:
	if is_queued_for_deletion():
		return
	if body is CharacterBody2D and body.velocity.y >= 0.0:
		body.velocity.y = bounce_impulse
		if death_particles_scene:
			var particles := death_particles_scene.instantiate() as GPUParticles2D
			particles.global_position = global_position
			get_parent().add_child(particles)
		queue_free()


func _on_hit_area_body_entered(body: Node2D) -> void:
	if is_queued_for_deletion():
		return
	if body.is_in_group("player") and body.has_method("take_damage"):
		if body is CharacterBody2D and body.velocity.y > 0.0 and body.global_position.y < global_position.y:
			return
		body.take_damage(damage)

class_name PlayerFallState
extends State

@export var player: CharacterBody2D
@export var animated_sprite: AnimatedSprite2D


func enter() -> void:
	if animated_sprite:
		animated_sprite.play("fall")


func physics_update(delta: float) -> void:
	player.apply_gravity(delta)
	var direction := Input.get_axis("move_left", "move_right")
	player.apply_movement(direction, delta)

	if player.is_on_floor():
		var sprite: Node2D = animated_sprite
		if not sprite and player:
			sprite = player.get_node_or_null("Sprite2D") as Node2D
		if sprite:
			sprite.scale = Vector2(1.25, 0.75)
			var tween := player.create_tween()
			tween.tween_property(sprite, "scale", Vector2.ONE, 0.15)

		if direction != 0.0:
			transitioned.emit(self, "run")
		else:
			transitioned.emit(self, "idle")

class_name GameCamera
extends Camera2D

var _shake_timer: float = 0.0
var _shake_strength: float = 0.0


func _process(delta: float) -> void:
	if _shake_timer > 0.0:
		_shake_timer -= delta
		offset = Vector2(
			randf_range(-_shake_strength, _shake_strength),
			randf_range(-_shake_strength, _shake_strength)
		)
	else:
		offset = Vector2.ZERO


func apply_shake(strength: float = 8.0, duration: float = 0.15) -> void:
	_shake_strength = strength
	_shake_timer = duration

class_name PlayerJumpState
extends State

@export var player: CharacterBody2D
@export var animated_sprite: AnimatedSprite2D


func enter() -> void:
	if animated_sprite:
		animated_sprite.play("jump")
	var sprite: Node2D = animated_sprite
	if not sprite and player:
		sprite = player.get_node_or_null("Sprite2D") as Node2D
	if sprite:
		sprite.scale = Vector2(0.75, 1.25)
		var tween := player.create_tween()
		tween.tween_property(sprite, "scale", Vector2.ONE, 0.15)

	if player and player.has_method("play_jump_sound"):
		player.play_jump_sound()

	player.velocity.y = player.jump_velocity


func physics_update(delta: float) -> void:
	player.apply_gravity(delta)
	var direction := Input.get_axis("move_left", "move_right")
	player.apply_movement(direction, delta)

	if Input.is_action_just_released("jump") and player.velocity.y < 0.0:
		player.velocity.y *= 0.5

	if player.velocity.y >= 0.0:
		transitioned.emit(self, "fall")

extends Area2D

@export var sparks_scene: PackedScene = preload("res://effects/coin_sparks.tscn")


func _ready() -> void:
	body_entered.connect(_on_body_entered)


func _on_body_entered(body: Node2D) -> void:
	if not body.is_in_group("player"):
		return

	if sparks_scene:
		var sparks := sparks_scene.instantiate() as GPUParticles2D
		sparks.global_position = global_position
		get_parent().add_child(sparks)

	var audio := get_node_or_null("CoinAudio") as AudioStreamPlayer2D
	if audio:
		audio.pitch_scale = randf_range(0.95, 1.25)
		audio.play()
		$Sprite2D.visible = false
		$CollisionShape2D.set_deferred("disabled", true)
		await audio.finished

	queue_free()

shader_type canvas_item;

uniform float flash_modifier : hint_range(0.0, 1.0) = 0.0;
uniform vec4 flash_color : source_color = vec4(1.0, 1.0, 1.0, 1.0);

void fragment() {
	vec4 color = texture(TEXTURE, UV);
	vec3 mixed_rgb = mix(color.rgb, flash_color.rgb, flash_modifier);
	COLOR = vec4(mixed_rgb, color.a);
}

class_name Player
extends CharacterBody2D

signal health_changed(new_health: int)

@export var max_health: int = 3
var health: int = 3

@onready var sprite_2d: Sprite2D = $Sprite2D


func _ready() -> void:
	add_to_group("player")
	health = max_health


func apply_gravity(delta: float) -> void:
	if not is_on_floor():
		velocity.y += 980.0 * delta


func apply_movement(direction: float, _delta: float) -> void:
	velocity.x = direction * 200.0
	if direction != 0.0 and sprite_2d:
		sprite_2d.flip_h = direction < 0.0
	move_and_slide()


func take_damage(amount: int = 1) -> void:
	health -= amount
	health_changed.emit(health)

	if sprite_2d and sprite_2d.material is ShaderMaterial:
		var mat := sprite_2d.material as ShaderMaterial
		mat.set_shader_parameter("flash_modifier", 1.0)
		var tween := create_tween()
		tween.tween_property(mat, "shader_parameter/flash_modifier", 0.0, 0.2)

