extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var sign_node := await instantiate_scene("res://objects/sign.tscn")
	if not check("sign_scene", sign_node != null, "La scena res://objects/sign.tscn deve caricarsi senza errori"):
		return
	var area := find_by_name(sign_node, "InteractionArea") as Area2D
	var sprite := find_by_name(sign_node, "Sprite2D") as Sprite2D
	if not check("nodes", area != null and sprite != null and sprite.material is ShaderMaterial, "La scena Sign deve contenere InteractionArea e uno Sprite2D con ShaderMaterial"):
		return
	var mat := sprite.material as ShaderMaterial
	var player := CharacterBody2D.new()
	player.add_to_group("player")
	var col := CollisionShape2D.new()
	var rect := RectangleShape2D.new()
	rect.size = Vector2(16.0, 16.0)
	col.shape = rect
	player.add_child(col)
	sign_node.add_child(player)
	player.global_position = area.global_position
	await wait_physics_frames(4)
	var val_in = mat.get_shader_parameter("line_thickness")
	var thick_in := float(val_in) if val_in != null else 0.0
	check("entered", thick_in > 0.0, "Quando il giocatore entra in InteractionArea, line_thickness deve essere > 0.0")
	player.global_position = Vector2(9999.0, 9999.0)
	await wait_physics_frames(4)
	var val_out = mat.get_shader_parameter("line_thickness")
	var thick_out := float(val_out) if val_out != null else -1.0
	check("exited", thick_out == 0.0, "Quando il giocatore esce da InteractionArea, line_thickness deve tornare a 0.0")

