func _run_tests() -> void:
	var door_scene := await instantiate_scene("res://objects/door.tscn")
	if not check("door_scene", door_scene != null, "La scena res://objects/door.tscn deve caricarsi senza errori"):
		return
	var area := find_by_name(door_scene, "InteractionArea") as Area2D
	if not check("area", area != null, "Door deve contenere un'Area2D chiamata InteractionArea"):
		return
	var sprite := find_by_name(door_scene, "Sprite2D") as Sprite2D
	if not check("sprite", sprite != null and sprite.material is ShaderMaterial, "Lo Sprite2D della porta deve contenere uno ShaderMaterial"):
		return
	var mat := sprite.material as ShaderMaterial
	var dummy_player := CharacterBody2D.new()
	dummy_player.add_to_group("player")
	door_scene.add_child(dummy_player)
	dummy_player.global_position = area.global_position
	await wait_physics_frames(4)
	var thick_in = float(mat.get_shader_parameter("line_thickness"))
	check("thick_entered", thick_in > 0.0, "Avvicinando il giocatore alla porta, line_thickness deve essere > 0.0 (trovato %s)" % str(thick_in))
	dummy_player.global_position = Vector2(9999, 9999)
	await wait_physics_frames(4)
	var thick_out = float(mat.get_shader_parameter("line_thickness"))
	check("thick_exited", thick_out == 0.0, "Allontanando il giocatore dalla porta, line_thickness deve tornare a 0.0 (trovato %s)" % str(thick_out))

